  `racing_series_id` int unsigned DEFAULT NULL,
  `profile_image` varchar(255) DEFAULT NULL,
  `season_id` int unsigned DEFAULT NULL,
  `role` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `piloto_team_id_index` (`team_id`),
