DROP TABLE IF EXISTS `session_result`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `session_result` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `session_id` int unsigned NOT NULL,
  `position` int DEFAULT NULL,
  `piloto_id` int unsigned DEFAULT NULL,
  `number_of_laps` int DEFAULT NULL,
  `dnf` tinyint(1) NOT NULL DEFAULT '0',
  `dns` tinyint(1) NOT NULL DEFAULT '0',
  `dsq` tinyint(1) NOT NULL DEFAULT '0',
  `duration` varchar(255) DEFAULT NULL,
  `gap_to_leader` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `session_result_session_id_index` (`session_id`),
  KEY `session_result_piloto_id_index` (`piloto_id`),
  CONSTRAINT `session_result_piloto_id_foreign` FOREIGN KEY (`piloto_id`) REFERENCES `piloto` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `session_result_session_id_foreign` FOREIGN KEY (`session_id`) REFERENCES `sesion` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8996 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
