DROP TABLE IF EXISTS `temporada`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `temporada` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `year` int NOT NULL,
  `racing_series_id` int unsigned NOT NULL,
  `winner_driver_id` int unsigned DEFAULT NULL,
  `winner_team_id` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `temporada_racing_series_id_index` (`racing_series_id`),
  KEY `temporada_winner_driver_id_index` (`winner_driver_id`),
  KEY `temporada_winner_team_id_index` (`winner_team_id`),
  CONSTRAINT `temporada_racing_series_id_foreign` FOREIGN KEY (`racing_series_id`) REFERENCES `categoria` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `temporada_winner_driver_id_foreign` FOREIGN KEY (`winner_driver_id`) REFERENCES `piloto` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `temporada_winner_team_id_foreign` FOREIGN KEY (`winner_team_id`) REFERENCES `escuderia` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
